<?php
require_once __DIR__ . '/_vault_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='GET'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=vault_db(); $actor=vault_require_auth(); $owner=vault_owner_from_request($db,[], $actor); vault_log($db,$owner,$actor,null,'view'); $folder=(int)($_GET['folder_id']??0); if(!vault_folder_owned($db,$folder,$owner)){ApiResponse::notFound('Vault folder not found.');exit;} $fs=$db->prepare('SELECT * FROM vault_folders WHERE owner_id=:owner AND deleted_at IS NULL AND (:folder=0 AND parent_folder_id IS NULL OR parent_folder_id=:folder) ORDER BY name ASC'); $fs->execute(['owner'=>$owner,'folder'=>$folder]); $ds=$db->prepare('SELECT * FROM vault_documents WHERE owner_id=:owner AND deleted_at IS NULL AND (:folder=0 AND folder_id IS NULL OR folder_id=:folder) ORDER BY updated_at DESC,id DESC'); $ds->execute(['owner'=>$owner,'folder'=>$folder]); $ps=$db->prepare("SELECT vp.authorized_user_id,u.full_name,u.username,vp.status FROM vault_permissions vp INNER JOIN users u ON u.id=vp.authorized_user_id WHERE vp.owner_id=:owner ORDER BY u.full_name ASC"); $ps->execute(['owner'=>$owner]); ApiResponse::success(['owner_id'=>$owner,'vault_verified'=>vault_verified(),'vault_verified_until'=>vault_verified_until(),'folders'=>array_map('vault_format_folder',$fs->fetchAll(PDO::FETCH_ASSOC)),'documents'=>array_map('vault_format_doc',$ds->fetchAll(PDO::FETCH_ASSOC)),'permissions'=>$ps->fetchAll(PDO::FETCH_ASSOC)],'Vault loaded.'); }catch(Throwable $e){Logger::error('Vault list failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to load vault.');}
?>
